INSERT INTO events (id, public_id, organizer_id, club_id, category_id, venue_id, title, slug, summary, description, banner_path, starts_at, ends_at, capacity, confirmed_count, status, approved_by, approved_at, created_at, deleted_at) VALUES
  (1, '380885b0-9d94-4b69-bef3-68388a658a6e', 3, 3, 1, 2, 'Tech Talk: Building Real Products with Generative AI', 'tech-talk-building-real-products-with-generative-ai-1', 'Engineers from regional startups share how they ship LLM-powered features to production.', 'A practical session on prompt design, evaluation, cost control and safety when integrating large language models into real products. Includes a live demo and an open Q&A with practitioners.', 'seed/genai.jpg', TIMESTAMPADD(MINUTE, -56760, @today), TIMESTAMPADD(MINUTE, -56640, @today), 250, 205, 'completed', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, -56760, @today)), TIMESTAMPADD(DAY, -20, TIMESTAMPADD(MINUTE, -56760, @today)), NULL),
  (2, '93682835-ad15-4982-978a-c0225b9f80bc', 4, 2, 2, 10, 'Career Fair Prep: CV and LinkedIn Clinic', 'career-fair-prep-cv-and-linkedin-clinic-2', 'One-to-one CV reviews and LinkedIn profile makeovers before the Career Fair.', 'Career Services consultants review your CV line by line, help you write a strong LinkedIn headline and summary, and run short mock elevator pitches. Bring a printed or digital copy of your CV.', 'seed/cvclinic.jpg', TIMESTAMPADD(MINUTE, -46920, @today), TIMESTAMPADD(MINUTE, -46740, @today), 45, 45, 'completed', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, -46920, @today)), TIMESTAMPADD(DAY, -11, TIMESTAMPADD(MINUTE, -46920, @today)), NULL),
  (3, 'b0a148aa-7d14-4c1d-af68-2c9befbdeea5', 5, 6, 3, 14, 'Lakeside Acoustic Night', 'lakeside-acoustic-night-3', 'An evening of live acoustic performances by student bands by the lake.', 'The Performing Arts Society hosts eight student acts performing original songs and covers. Food trucks open from 7pm. Bring a mat and enjoy the lakeside sunset.', 'seed/acoustic.jpg', TIMESTAMPADD(MINUTE, -36270, @today), TIMESTAMPADD(MINUTE, -36090, @today), 250, 190, 'completed', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, -36270, @today)), TIMESTAMPADD(DAY, -25, TIMESTAMPADD(MINUTE, -36270, @today)), NULL),
  (4, '579dec85-a6b1-4df2-a017-56000ff25a1f', 3, 3, 5, 8, 'Intro to Python for Non-Programmers', 'intro-to-python-for-non-programmers-4', 'A hands-on first step into programming for students from any school.', 'No experience needed. Learn variables, loops and functions by automating a simple spreadsheet task. Lab computers are provided; laptops are welcome.', 'seed/python.jpg', TIMESTAMPADD(MINUTE, -26520, @today), TIMESTAMPADD(MINUTE, -26340, @today), 40, 39, 'completed', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, -26520, @today)), TIMESTAMPADD(DAY, -23, TIMESTAMPADD(MINUTE, -26520, @today)), NULL),
  (5, '4106acfb-f00c-4c42-8aa8-430033ac989b', 6, 11, 4, 1, 'Inter-Faculty Futsal Cup', 'inter-faculty-futsal-cup-5', 'Schools compete in a one-day knockout futsal tournament.', 'Sixteen teams representing every school compete for the Inter-Faculty Cup. Spectators are welcome; registration secures a seat in the stands and a supporter wristband.', 'seed/futsal.jpg', TIMESTAMPADD(MINUTE, -16740, @today), TIMESTAMPADD(MINUTE, -16260, @today), 300, 150, 'completed', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, -16740, @today)), TIMESTAMPADD(DAY, -21, TIMESTAMPADD(MINUTE, -16740, @today)), NULL),
  (6, 'cc2ff992-582a-4424-8658-a07da24cc76b', 7, 4, 7, 3, 'Startup Pitch Night', 'startup-pitch-night-6', 'Student founders pitch to a panel of angel investors and incubators.', 'Ten shortlisted student teams have five minutes each to pitch, followed by panel feedback. The audience votes for the People''s Choice award.', 'seed/pitch.jpg', TIMESTAMPADD(MINUTE, -10440, @today), TIMESTAMPADD(MINUTE, -10260, @today), 180, 140, 'completed', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, -10440, @today)), TIMESTAMPADD(DAY, -27, TIMESTAMPADD(MINUTE, -10440, @today)), NULL),
  (7, '14b56a0c-c35c-4193-9c2e-5a55898c7d3d', 8, 9, 8, 9, 'Beach Cleanup Volunteer Briefing', 'beach-cleanup-volunteer-briefing-7', 'Safety briefing and team allocation for the upcoming coastal clean-up.', 'Mandatory briefing for registered volunteers covering safety, waste sorting and transport arrangements. Volunteer hours count towards the co-curricular record.', 'seed/cleanup.jpg', TIMESTAMPADD(MINUTE, -6240, @today), TIMESTAMPADD(MINUTE, -6150, @today), 45, 38, 'completed', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, -6240, @today)), TIMESTAMPADD(DAY, -22, TIMESTAMPADD(MINUTE, -6240, @today)), NULL),
  (8, 'c985e170-c209-4d98-a30e-2b19a5ce0290', 9, 1, 6, 1, 'CNS Fest: Clubs and Societies Festival', 'cns-fest-clubs-and-societies-festival-8', 'Meet the clubs and societies of Lakeside Campus in one place.', 'Clubs and societies set up booths, performances and games across the Grand Hall. Sign up for the clubs you like on the spot.', 'seed/freshers.jpg', TIMESTAMPADD(MINUTE, -85800, @today), TIMESTAMPADD(MINUTE, -85440, @today), 800, 290, 'archived', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, -85800, @today)), TIMESTAMPADD(DAY, -30, TIMESTAMPADD(MINUTE, -85800, @today)), NULL),
  (9, 'aea3ba35-eeef-4d00-b739-67586ef24fb4', 3, 3, 7, 6, 'Hack Lakeside: Smart Campus Challenge', 'hack-lakeside-smart-campus-challenge-9', 'A 24-hour hackathon to build solutions for a smarter, greener campus.', 'Teams of three to four build prototypes around energy, mobility and student wellbeing on campus. Mentors from industry are on site at Taylor''s Makerspace; final demos tomorrow afternoon.', 'seed/hackathon.jpg', TIMESTAMPADD(MINUTE, -150, @now), TIMESTAMPADD(MINUTE, 1290, @now), 40, 36, 'ongoing', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, -150, @now)), TIMESTAMPADD(DAY, -10, TIMESTAMPADD(MINUTE, -150, @now)), NULL),
  (10, '78f00042-0a1d-481d-9930-a903a4965c27', 3, 3, 5, 8, 'Cloud and DevOps Bootcamp', 'cloud-and-devops-bootcamp-10', 'Deploy a containerised web app with CI/CD in one afternoon. Only one seat left!', 'Hands-on lab covering Docker, GitHub Actions and cloud deployment. Each participant leaves with a live deployed project. Seats are limited to lab capacity.', 'seed/lastseat.jpg', TIMESTAMPADD(MINUTE, 5160, @today), TIMESTAMPADD(MINUTE, 5340, @today), 30, 29, 'published', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, 5160, @today)), TIMESTAMPADD(DAY, -11, TIMESTAMPADD(MINUTE, 5160, @today)), NULL),
  (11, '6747ab53-791b-4751-a8d6-33f3de1b7563', 9, 1, 4, 9, 'Mental Health Awareness Workshop', 'mental-health-awareness-workshop-11', 'Practical tools for managing stress during assessment season.', 'Facilitated by Student Development. Covers recognising burnout, healthy study routines, and where to find support on campus. A safe, confidential space.', 'seed/wellness.jpg', TIMESTAMPADD(MINUTE, 6420, @today), TIMESTAMPADD(MINUTE, 6540, @today), 40, 40, 'published', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, 6420, @today)), TIMESTAMPADD(DAY, -14, TIMESTAMPADD(MINUTE, 6420, @today)), NULL),
  (12, 'dcb37082-a53c-40c4-aa56-9848b6b95266', 4, 2, 2, 2, 'Industry Night: Fintech Careers in Southeast Asia', 'industry-night-fintech-careers-in-southeast-asia-12', 'Hiring managers from regional fintech and BNPL companies talk careers and internships.', 'A panel and networking evening with speakers from payments, lending and regulatory technology. Learn which skills employers look for and how to land an internship.', 'seed/fintech.jpg', TIMESTAMPADD(MINUTE, 9720, @today), TIMESTAMPADD(MINUTE, 9870, @today), 250, 140, 'published', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, 9720, @today)), TIMESTAMPADD(DAY, -13, TIMESTAMPADD(MINUTE, 9720, @today)), NULL),
  (13, '1e2a9ffe-43a3-4f89-9f26-2a64f51ad83a', 7, 4, 5, 10, 'Design Thinking Sprint', 'design-thinking-sprint-13', 'Go from problem to tested prototype in four hours.', 'A guided sprint using the double-diamond method. Work in mixed-discipline teams to define a campus problem, ideate, prototype and test with real users.', 'seed/design.jpg', TIMESTAMPADD(MINUTE, 10620, @today), TIMESTAMPADD(MINUTE, 10860, @today), 35, 22, 'published', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, 10620, @today)), TIMESTAMPADD(DAY, -21, TIMESTAMPADD(MINUTE, 10620, @today)), NULL),
  (14, '35258928-a535-4016-b9be-2d166c3451af', 5, 8, 3, 1, 'Cultural Night: Taste of Nations', 'cultural-night-taste-of-nations-14', 'Food, music and performances from over 30 nationalities on campus.', 'International and local student associations present traditional food stalls, dance and music performances, and a cultural fashion parade.', 'seed/cultural.jpg', TIMESTAMPADD(MINUTE, 15480, @today), TIMESTAMPADD(MINUTE, 15720, @today), 600, 260, 'published', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, 15480, @today)), TIMESTAMPADD(DAY, -17, TIMESTAMPADD(MINUTE, 15480, @today)), NULL),
  (15, 'f480a9a2-75cd-42d2-b6a0-0e11fc78169e', 6, 12, 4, 1, 'Badminton Open Doubles', 'badminton-open-doubles-15', 'Open doubles tournament for all skill levels.', 'Register individually or as a pair. Matches are seeded by skill level. Shuttlecocks provided; bring your own racket.', 'seed/badminton.jpg', TIMESTAMPADD(MINUTE, 17820, @today), TIMESTAMPADD(MINUTE, 18180, @today), 128, 96, 'published', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, 17820, @today)), TIMESTAMPADD(DAY, -18, TIMESTAMPADD(MINUTE, 17820, @today)), NULL),
  (16, 'f8870e8e-bd70-4efc-89d4-71f01f0ac651', 3, 3, 7, 7, 'Cybersecurity CTF Qualifier', 'cybersecurity-ctf-qualifier-16', 'Capture-the-flag qualifier for the national inter-university competition.', 'Solve web, cryptography and forensics challenges individually. Top performers qualify to represent the university. Basic Linux knowledge recommended.', 'seed/ctf.jpg', TIMESTAMPADD(MINUTE, 20760, @today), TIMESTAMPADD(MINUTE, 21060, @today), 60, 47, 'published', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, 20760, @today)), TIMESTAMPADD(DAY, -10, TIMESTAMPADD(MINUTE, 20760, @today)), NULL),
  (17, '64cd68d0-2c34-4d58-99e2-ec527980f7de', 8, 10, 5, 3, 'Public Speaking Masterclass', 'public-speaking-masterclass-17', 'Build confidence and structure for presentations and interviews.', 'An interactive masterclass on storytelling, voice and body language, with short practice rounds and peer feedback.', 'seed/speaking.jpg', TIMESTAMPADD(MINUTE, 23940, @today), TIMESTAMPADD(MINUTE, 24060, @today), 150, 63, 'published', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, 23940, @today)), TIMESTAMPADD(DAY, -26, TIMESTAMPADD(MINUTE, 23940, @today)), NULL),
  (18, 'b3800e45-32ec-40ed-9085-977621dc40c1', 8, 9, 8, 1, 'Blood Donation Drive', 'blood-donation-drive-18', 'Donate blood with the National Blood Centre on campus.', 'Registration reserves a screening slot. Please eat well and bring your IC or passport. Donors receive a certificate and refreshments.', 'seed/blood.jpg', TIMESTAMPADD(MINUTE, 29340, @today), TIMESTAMPADD(MINUTE, 29760, @today), 300, 85, 'published', 1, TIMESTAMPADD(DAY, -7, TIMESTAMPADD(MINUTE, 29340, @today)), TIMESTAMPADD(DAY, -30, TIMESTAMPADD(MINUTE, 29340, @today)), NULL),
  (19, 'c03d78ef-4ec8-4076-adea-a92e4d32a879', 3, 3, 1, 11, 'Robotics Club Showcase', 'robotics-club-showcase-19', 'Autonomous robots, drones and live demos from the Robotics Club.', 'Members demonstrate line-following robots, a drone obstacle course and a robotic arm controlled by computer vision.', 'seed/robotics.jpg', TIMESTAMPADD(MINUTE, 26760, @today), TIMESTAMPADD(MINUTE, 26940, @today), 60, 0, 'pending_approval', NULL, NULL, TIMESTAMPADD(DAY, -29, TIMESTAMPADD(MINUTE, 26760, @today)), NULL),
  (20, '6fa525da-d236-4716-ac30-a62149411005', 5, 7, 3, 4, 'Film Screening and Director Q&A', 'film-screening-and-director-q-a-20', 'Screening of an award-winning Malaysian short film followed by a director Q&A.', 'The School of Media and Communication hosts a screening and an open conversation about independent filmmaking in Malaysia.', 'seed/film.jpg', TIMESTAMPADD(MINUTE, 31380, @today), TIMESTAMPADD(MINUTE, 31560, @today), 150, 0, 'pending_approval', NULL, NULL, TIMESTAMPADD(DAY, -23, TIMESTAMPADD(MINUTE, 31380, @today)), NULL),
  (21, '6583bfbb-16e4-4ff8-b370-28156eb99c19', 7, 5, 2, 12, 'Investment 101 for Students', 'investment-101-for-students-21', 'Budgeting, saving and the basics of investing, explained simply.', 'Learn how compound growth works, the difference between saving and investing, and how to avoid common scams targeting students.', 'seed/invest.jpg', TIMESTAMPADD(MINUTE, 13920, @today), TIMESTAMPADD(MINUTE, 14040, @today), 40, 0, 'pending_approval', NULL, NULL, TIMESTAMPADD(DAY, -27, TIMESTAMPADD(MINUTE, 13920, @today)), NULL),
  (22, '3712f0b5-dfc8-4c69-9e36-17ebd96e837e', 3, 3, 1, 8, 'Data Science Study Jam', 'data-science-study-jam-22', 'Peer-led study session on pandas and data visualisation.', 'Work through guided notebooks on cleaning and visualising a real campus dataset. This draft overlaps the Cloud and DevOps Bootcamp in the Huawei Lab and is used to demonstrate venue clash detection.', 'seed/studyjam.jpg', TIMESTAMPADD(MINUTE, 5220, @today), TIMESTAMPADD(MINUTE, 5340, @today), 35, 0, 'draft', NULL, NULL, TIMESTAMPADD(DAY, -22, TIMESTAMPADD(MINUTE, 5220, @today)), NULL),
  (23, '92a67093-98c6-4eec-bd0b-6d4a8b29c433', 8, 9, 8, 13, 'Volunteer Orientation: New Intake', 'volunteer-orientation-new-intake-23', 'Orientation for students joining the Community Service Club.', 'An introduction to ongoing community projects, volunteer hour tracking and upcoming outreach programmes.', 'seed/volorient.jpg', TIMESTAMPADD(MINUTE, 36600, @today), TIMESTAMPADD(MINUTE, 36720, @today), 45, 0, 'draft', NULL, NULL, TIMESTAMPADD(DAY, -29, TIMESTAMPADD(MINUTE, 36600, @today)), NULL),
