-- =============================================================================
--  Taylor's Event Management Platform - Demo Seed Data
--  Load AFTER schema.sql on a fresh database (schema.sql drops & recreates it).
--
--  All dates are RELATIVE to the moment the seed is loaded (@today / @now),
--  so on presentation day there are always: past events with analytics,
--  one event happening right now (live QR check-in), upcoming events,
--  a "last seat" event (concurrency demo), a full event with a waitlist
--  (auto-promotion demo), pending approvals and a draft that clashes with a
--  booked venue (conflict-detection demo).
--
--  Demo accounts (password for every seeded account: Demo@12345)
--    admin@taylors.edu.my        -> admin      (Student Life Office)
--    organizer@taylors.edu.my    -> organizer  (Taylor's Computing Society)
--    student@sd.taylors.edu.my   -> student    (School of Computer Science)
--
--  NOTE: venue names/buildings are realistic placeholders. Replace them with
--  the exact Lakeside Campus room names before the presentation.
-- =============================================================================

SET NAMES utf8mb4;
SET time_zone = '+08:00';
USE taylors_events;

SET @seed_mode = 1;           -- relax "insert as draft" + skip trigger audit
SET @app_user_id = NULL;
SET @app_ip = '127.0.0.1';
SET @now   = NOW();
SET @today = CAST(CURDATE() AS DATETIME);

START TRANSACTION;

