-- Users (password for all: Demo@12345, Argon2id) ---------------------------




UPDATE users SET failed_login_count = 5, locked_until = TIMESTAMPADD(MINUTE, 12, @now) WHERE id = 17;

-- Clubs and offices that host events ----------------------------------------


-- Events ------------------------------------------------------------------

-- Registrations -----------------------------------------------------------










-- Door scan log: one admitted scan per check-in, plus rejected attempts -----
SELECT r.event_id, r.id, r.checked_in_by, 'admitted', SHA2(CONCAT('seed', r.id), 256), '10.20.4.17', r.checked_in_at
  FROM registrations r WHERE r.checked_in_at IS NOT NULL ORDER BY r.checked_in_at;
SELECT r.event_id, r.id, r.checked_in_by, 'duplicate', SHA2(CONCAT('seed', r.id), 256), '10.20.4.17', TIMESTAMPADD(MINUTE, 6, r.checked_in_at)
  FROM registrations r WHERE r.event_id = 9 AND r.checked_in_at IS NOT NULL ORDER BY r.id LIMIT 2;

-- Captured emails (transport = log) -----------------------------------------

-- Ratings (only attendees of finished events; validated by trg_ratings_bi) --



-- Notifications for the demo student ---------------------------------------

-- Pending-approval notification for the admin
SELECT 1, 'event_updated', 'Approval required',
       CONCAT('"', title, '" is waiting for your approval.'), '/admin/approvals', TIMESTAMPADD(HOUR, -5, @now)
  FROM events WHERE status = 'pending_approval';

-- One soft-delete record so the audit page is not empty on first load
SELECT organizer_id, 'event.delete', 'event', id,
       JSON_OBJECT('title', title, 'status', status, 'deleted_at', NULL),
       JSON_OBJECT('title', title, 'status', status, 'deleted_at', deleted_at),
       '127.0.0.1', deleted_at
  FROM events WHERE deleted_at IS NOT NULL;

COMMIT;

SET @seed_mode = NULL;

-- Integrity check: confirmed_count must equal the real number of confirmed rows.
SELECT e.id, e.title, e.confirmed_count,
       (SELECT COUNT(*) FROM registrations r WHERE r.event_id = e.id AND r.status = 'confirmed') AS actual
  FROM events e
HAVING e.confirmed_count <> actual;
